  --bg-option: #252840;
  --bg-option-hover: #2d3155;
  --bg-option-checked: #1e2a4a;
  --border: #2e3249;
  --border-focus: #6c7aff;
  --border-checked: #5b6cf9;
  --accent: #6c7aff;
  --accent-light: #a5adff;
  --text-primary: #e8eaf6;
  --text-secondary: #8b90b8;
  --text-help: #6b7099;
  --success: #4ade80;
  --error: #f87171;
  --btn-bg: #5b6cf9;
  --btn-hover: #6c7aff;
  --btn-active: #4a5ae0;
  --shadow-card: 0 4px 24px rgba(0, 0, 0, 0.4);
  --radius: 12px;
  --radius-sm: 8px;
  --transition: 150ms ease;
}

body {
  background-color: var(--bg-page);
  color: var(--text-primary);
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 48px 16px 80px;
}

#root {
  width: 100%;
  max-width: 680px;
}

/* Header */
.quiz-header {
  text-align: center;
  margin-bottom: 40px;
}

.quiz-header h1 {
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -0.5px;
  background: linear-gradient(135deg, #a5adff 0%, #6c7aff 50%, #c084fc 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 8px;
}

.quiz-header p {
  color: var(--text-secondary);
  font-size: 0.95rem;
}

/* Progress bar */
.progress-bar-wrap {
  background: var(--border);
  border-radius: 999px;
  height: 4px;
  margin-bottom: 40px;
  overflow: hidden;
}

.progress-bar {
  height: 100%;
  background: linear-gradient(90deg, #6c7aff, #c084fc);
  border-radius: 999px;
  transition: width 500ms ease;
}

/* Form field (question card) */
.form-field {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 28px;
  margin-bottom: 20px;
  box-shadow: var(--shadow-card);
  transition: border-color var(--transition);
}

.form-field:focus-within {
  border-color: var(--border-focus);
}

.question-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.question-number {
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--accent-light);
  background: rgba(108, 122, 255, 0.12);
  border: 1px solid rgba(108, 122, 255, 0.25);
  padding: 3px 10px;
  border-radius: 999px;
}

.form-field legend {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-primary);
  display: block;
  margin-bottom: 6px;
  line-height: 1.4;
}

.help-text {
  font-size: 0.85rem;
  color: var(--text-help);
  margin-bottom: 18px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.help-text svg {
  flex-shrink: 0;
  opacity: 0.7;
}

/* Options list */
.options-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* Checkbox option */
.option-label {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  background: var(--bg-option);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), transform var(--transition);
  user-select: none;
  position: relative;
}

.option-label:hover {
  background: var(--bg-option-hover);
  border-color: var(--accent);
}

.option-label:active {
  transform: scale(0.99);
}

/* Hidden native checkbox */
.option-label input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

/* Custom checkbox */
.custom-checkbox {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  border: 2px solid var(--border-focus);
  border-radius: 5px;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition), border-color var(--transition);
}

.custom-checkbox svg {
  opacity: 0;
  transform: scale(0.5);
  transition: opacity var(--transition), transform var(--transition);
}

/* Checked state */
.option-label input[type="checkbox"]:checked ~ .custom-checkbox {
  background: var(--accent);
  border-color: var(--accent);
}

.option-label input[type="checkbox"]:checked ~ .custom-checkbox svg {
  opacity: 1;
  transform: scale(1);
}

.option-label:has(input[type="checkbox"]:checked) {
  background: var(--bg-option-checked);
  border-color: var(--border-checked);
}

/* Focus ring */
.option-label input[type="checkbox"]:focus-visible ~ .custom-checkbox {
  outline: 2px solid var(--accent-light);
  outline-offset: 2px;
}

.option-text {
  font-size: 0.95rem;
  color: var(--text-primary);
  flex: 1;
}

.option-label:has(input[type="checkbox"]:checked) .option-text {
  color: #c5caff;
}

/* Submit button */
.submit-wrap {
  margin-top: 32px;
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  align-items: center;
}

.btn-submit {
  background: var(--btn-bg);
  color: #fff;
  font-size: 0.95rem;
  font-weight: 600;
  padding: 13px 32px;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  box-shadow: 0 4px 16px rgba(91, 108, 249, 0.35);
  letter-spacing: 0.3px;
}

.btn-submit:hover {
  background: var(--btn-hover);
  box-shadow: 0 6px 22px rgba(108, 122, 255, 0.45);
  transform: translateY(-1px);
}

.btn-submit:active {
  background: var(--btn-active);
  transform: translateY(0);
}

.btn-submit:focus-visible {
  outline: 2px solid var(--accent-light);
  outline-offset: 3px;
}

.btn-reset {
  background: transparent;
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  padding: 13px 20px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: color var(--transition), border-color var(--transition);
}

.btn-reset:hover {
  color: var(--text-primary);
  border-color: var(--text-secondary);
}

.btn-reset:focus-visible {
  outline: 2px solid var(--accent-light);
  outline-offset: 3px;
}

/* Results panel */
.results-panel {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 32px;
  margin-top: 24px;
  box-shadow: var(--shadow-card);
  animation: slideUp 300ms ease forwards;
}

@keyframes slideUp {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}

.results-panel h2 {
  font-size: 1.35rem;
  font-weight: 700;
  margin-bottom: 6px;
}

.score-line {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 24px;
}

.score-value {
  font-size: 2.8rem;
  font-weight: 800;
  display: block;
  margin-bottom: 4px;
}

.score-value.perfect { color: var(--success); }
.score-value.good    { color: #facc15; }
.score-value.low     { color: var(--error); }

.result-item {
  padding: 14px 0;
  border-top: 1px solid var(--border);
}

.result-item:last-child { border-bottom: 1px solid var(--border); }

.result-question {
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.result-badge {
  font-size: 0.72rem;
  padding: 2px 9px;
  border-radius: 999px;
  font-weight: 600;
}

.result-badge.correct {
  background: rgba(74, 222, 128, 0.15);
  color: var(--success);
  border: 1px solid rgba(74, 222, 128, 0.3);
}

.result-badge.incorrect {
  background: rgba(248, 113, 113, 0.15);
  color: var(--error);
  border: 1px solid rgba(248, 113, 113, 0.3);
}

.result-detail {
  font-size: 0.83rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.result-detail em {
  color: var(--success);
  font-style: normal;
}

/* Validation error */
.field-error {
  font-size: 0.82rem;
  color: var(--error);
  margin-top: 12px;
  display: none;
  align-items: center;
  gap: 5px;
}

.field-error.visible {
  display: flex;
}

.form-field.has-error {
  border-color: rgba(248, 113, 113, 0.5);
}
