      <div class="progress-bar" style="width:${pct}%"></div>
    </div>`;
}

function scoreClass(pct) {
  if (pct === 100) return "perfect";
  if (pct >= 50) return "good";
  return "low";
}

function renderResults(state) {
  let correct = 0;
  const items = QUESTIONS.map((q) => {
    const chosen = state[q.id] ?? new Set();
    const isCorrect =
      chosen.size === q.correct.length &&
      q.correct.every((id) => chosen.has(id));
    if (isCorrect) correct++;

    const correctNames = q.correct
      .map((id) => q.options.find((o) => o.id === id)?.text)
      .join(", ");

    return `
      <li class="result-item">
        <div class="result-question">
          ${q.text}
          <span class="result-badge ${isCorrect ? "correct" : "incorrect"}">${isCorrect ? "Correct" : "Incorrect"}</span>
        </div>
        <p class="result-detail">Correct answer${q.correct.length > 1 ? "s" : ""}: <em>${correctNames}</em></p>
      </li>`;
  });

  const pct = Math.round((correct / QUESTIONS.length) * 100);
  const message =
    pct === 100
      ? "Perfect score! 🎉"
      : pct >= 67
      ? "Nice work!"
      : pct >= 34
      ? "Keep studying!"
      : "Better luck next time.";

  return `
    <section class="results-panel" aria-labelledby="results-heading">
      <h2 id="results-heading">${message}</h2>
      <p class="score-line">You answered ${correct} of ${QUESTIONS.length} questions correctly.</p>
      <span class="score-value ${scoreClass(pct)}" aria-label="Score: ${pct} percent">${pct}%</span>
      <ul aria-label="Question breakdown">
        ${items.join("")}
      </ul>
    </section>`;
}

// ── App state ─────────────────────────────────────────────────────────────────

const state = {
  answers: {},   // { [questionId]: Set<optionId> }
  submitted: false,
  errors: new Set(),
};

function countAnswered() {
  return QUESTIONS.filter((q) => (state.answers[q.id]?.size ?? 0) > 0).length;
}

// ── Render & patch ────────────────────────────────────────────────────────────

function render() {
  const root = document.getElementById("root");

  const questionHTML = QUESTIONS.map((q, i) =>
    renderQuestion({
      question: q,
      index: i,
      state: state.answers,
      errors: state.errors,
    })
  ).join("");

  root.innerHTML = `
    <header class="quiz-header">
      <h1>Computer Languages Quiz</h1>
      <p>Test your knowledge — select all answers that apply.</p>
    </header>
    ${renderProgress(countAnswered())}
    <main>
      <form id="quiz-form" novalidate aria-label="Computer languages quiz">
        ${questionHTML}
        <div class="submit-wrap">
          <button type="button" class="btn-reset" id="btn-reset">Reset</button>
          <button type="submit" class="btn-submit" id="btn-submit">
            Submit Quiz
          </button>
        </div>
      </form>
      ${state.submitted ? renderResults(state.answers) : ""}
    </main>`;

  attachListeners();

  if (state.submitted) {
    document
      .querySelector(".results-panel")
      ?.scrollIntoView({ behavior: "smooth", block: "start" });
  }
}

function attachListeners() {
  // Checkbox changes
  document.querySelectorAll('input[type="checkbox"]').forEach((cb) => {
    cb.addEventListener("change", (e) => {
      const questionId = e.target.name;
      if (!state.answers[questionId]) {
        state.answers[questionId] = new Set();
      }
      if (e.target.checked) {
        state.answers[questionId].add(e.target.value);
      } else {
        state.answers[questionId].delete(e.target.value);
      }
      // Clear error once user interacts
      if (state.answers[questionId].size > 0) {
        state.errors.delete(questionId);
      }
      updateProgress();
      updateFieldError(questionId);
    });
  });

  // Submit
  document.getElementById("quiz-form").addEventListener("submit", handleSubmit);

  // Reset
  document.getElementById("btn-reset").addEventListener("click", handleReset);
}

function handleSubmit(e) {
  e.preventDefault();
  state.errors.clear();

  QUESTIONS.forEach((q) => {
    if ((state.answers[q.id]?.size ?? 0) === 0) {
      state.errors.add(q.id);
    }
  });

  if (state.errors.size > 0) {
    // Re-render just the error states without full re-render
    QUESTIONS.forEach((q) => {
      const field = document.querySelector(`[data-question="${q.id}"]`);
      if (!field) return;
      const errEl = field.querySelector(".field-error");
      if (state.errors.has(q.id)) {
        field.classList.add("has-error");
        errEl.classList.add("visible");
      } else {
        field.classList.remove("has-error");
        errEl.classList.remove("visible");
      }
    });
    // Focus first errored field
    const firstErrorQ = QUESTIONS.find((q) => state.errors.has(q.id));
    if (firstErrorQ) {
      document
        .querySelector(`[data-question="${firstErrorQ.id}"]`)
        ?.scrollIntoView({ behavior: "smooth", block: "center" });
    }
    return;
  }

  state.submitted = true;
  render();
}

function handleReset() {
  state.answers = {};
  state.submitted = false;
  state.errors.clear();
  render();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function updateProgress() {
  const wrap = document.querySelector(".progress-bar-wrap");
  const bar = document.querySelector(".progress-bar");
  if (!bar || !wrap) return;
  const answered = countAnswered();
  const pct = Math.round((answered / QUESTIONS.length) * 100);
  bar.style.width = `${pct}%`;
  wrap.setAttribute("aria-valuenow", pct);
  wrap.setAttribute("aria-label", `Quiz progress: ${pct}%`);
}

function updateFieldError(questionId) {
  const field = document.querySelector(`[data-question="${questionId}"]`);
  if (!field) return;
  const errEl = field.querySelector(".field-error");
  if (state.errors.has(questionId)) {
    field.classList.add("has-error");
    errEl.classList.add("visible");
  } else {
    field.classList.remove("has-error");
    errEl.classList.remove("visible");
  }
}

// ── Boot ──────────────────────────────────────────────────────────────────────

